package com.wolinski.shop.orders.internal;

import java.util.Collection;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.concurrent.ConcurrentHashMap;
import org.springframework.stereotype.Repository;

@Repository
public class OrderRepository {

    private final Map<String, Order> orders = new ConcurrentHashMap<>();

    public void save(Order order) {
        orders.put(order.id(), order);
    }

    public Order get(String orderId) {
        Order order = orders.get(orderId);
        if (null == order) {
            throw new NoSuchElementException(orderId);
        }
        return order;
    }

    public Collection<Order> all() {
        return orders.values();
    }
}

package com.wolinski.shop.orders.internal;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.payments.internal.Payment;
import com.wolinski.shop.payments.internal.PaymentRepository;
import java.time.LocalDate;
import java.time.ZoneOffset;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

/** The nightly report for accounting. */
@Component
public class OrderReports {

    private final OrderRepository orders;
    private final PaymentRepository payments;

    public OrderReports(OrderRepository orders, PaymentRepository payments) {
        this.orders = orders;
        this.payments = payments;
    }

    public long placedToday() {
        LocalDate today = LocalDate.now(ZoneOffset.UTC);
        return orders.all().stream()
                .filter(order -> order.placedAt().atZone(ZoneOffset.UTC).toLocalDate().equals(today))
                .count();
    }

    public long placedYesterday() {
        LocalDate yesterday = LocalDate.now().minusDays(1);
        return orders.all().stream()
                .filter(order -> order.placedAt().atZone(ZoneOffset.UTC).toLocalDate().equals(yesterday))
                .count();
    }

    @Scheduled(cron = "0 0 1 * * *")
    public void nightly() {
        System.out.println("placed yesterday: " + placedYesterday() + ", revenue: " + capturedRevenue());
    }

    public Money capturedRevenue() {
        Money sum = Money.pln(0);
        for (Order order : orders.all()) {
            for (Payment payment : payments.findByOrderId(order.id())) {
                sum = sum.plus(payment.amount());
            }
        }
        return sum;
    }
}

package com.wolinski.shop.orders.internal;

import com.wolinski.shop.customers.api.CustomerFacade;
import com.wolinski.shop.notifications.api.Notifier;
import com.wolinski.shop.shipping.api.CarrierGateway;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

/** A customer sends an order back. */
@Component
public class OrderReturns {

    private final OrderRepository orders;
    private final CarrierGateway carrier;
    private final Notifier notifier;
    private final CustomerFacade customers;

    public OrderReturns(OrderRepository orders, CarrierGateway carrier, Notifier notifier, CustomerFacade customers) {
        this.orders = orders;
        this.carrier = carrier;
        this.notifier = notifier;
        this.customers = customers;
    }

    @Transactional
    public String startReturn(String orderId) {
        Order order = orders.get(orderId);
        if ("CANCELLED".equals(order.status())) {
            throw new IllegalStateException("A cancelled order cannot be returned");
        }
        order.changeStatus("RETURNING");
        String label = carrier.book("return-" + orderId);
        notifier.send(customers.emailOf(order.customerId()), "Return " + orderId, "Your return label: " + label);
        return label;
    }
}

